import torch,json
L=26
S={'col':[4097,1932,5730,6842,1806,2397],'mon':[2025,11489,333,9810],'wk':[10783,11825,11832,6762,10396],'gen':[1565,2871,11915,1010],'rom':[4058,2818,11507,2222],'fact':[633,4894,6821,2663,2442,6132],'ord':[9817,352,5661,9149]}
D=W(f'model.language_model.layers.{L}.mlp.down_proj.weight'); D=D/D.norm(dim=0,keepdim=True)
G=W(f'model.language_model.layers.{L}.mlp.gate_proj.weight'); G=G/G.norm(dim=1,keepdim=True)
U=W(f'model.language_model.layers.{L}.mlp.up_proj.weight'); U=U/U.norm(dim=1,keepdim=True)
def proj(s):
    st=torch.tensor(s)
    Q,_=torch.linalg.qr(D[:,st]); Qg,_=torch.linalg.qr(G[st].T); Qu,_=torch.linalg.qr(U[st].T)
    return (Q.T@D).norm(dim=0)+(Qg.T@G.T).norm(dim=0)+(Qu.T@U.T).norm(dim=0)
P={k:proj(v) for k,v in S.items()}
for tgt in ['col','wk']:
    excl=[e for e in S if e!=tgt]
    sc=P[tgt]-torch.stack([P[e] for e in excl]).max(0).values
    sc[torch.tensor(S[tgt])]=99
    for e in excl: sc[torch.tensor(S[e])]=-99
    o=torch.argsort(sc,descending=True)
    for K in [512,1024]:
        json.dump({'kind':'mlp_cluster','layer':L,'indices':o[:K].tolist()},open(f'/work/y_{tgt}{L}_{K}.json','w'))
print('ok')

